import { Api } from '../base/api';
export class AppApi extends Api {
    constructor(imageUrl, baseUrl, options) {
        super(baseUrl, options);
        this.imageUrl = imageUrl;
    }
    getProductsList() {
        return this.get('/product').then((data) => data.items.map((item) => (Object.assign(Object.assign({}, item), { image: this.imageUrl + item.image }))));
    }
    getProductItem(id) {
        return this.get(`/product/${id}`).then((item) => (Object.assign(Object.assign({}, item), { image: this.imageUrl + item.image })));
    }
    postOrder(order) {
        return this.post('/order', order);
    }
}
